using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CityGunStepProbe{static CityGunStepProbe(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("CityGunStepProbe.request"))return;File.Delete("CityGunStepProbe.request");try{var sc=SceneManager.GetActiveScene();var t=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Single(x=>x.name=="Gun Shop");var mesh=t.GetComponent<MeshFilter>().sharedMesh;var vv=mesh.vertices;var nn=mesh.normals;var groups=Enumerable.Range(0,vv.Length).Where(i=>vv[i].y>5.09f&&nn[i].z>.9f).GroupBy(i=>Mathf.Round(vv[i].z*1000)/1000).OrderByDescending(g=>g.Count());var b=new StringBuilder();foreach(var group in groups)b.AppendLine("UPPER FRONT Z="+group.Key+" count="+group.Count());Physics.SyncTransforms();foreach(float x in new[]{-10f,-7.5f,-5,-2.5f,0,2.5f,5,7.5f,10})foreach(float z in new[]{11.6f,12.4f,13.2f}){var p=t.TransformPoint(new Vector3(x,20,z));b.AppendLine("SAMPLE local x="+x+" z="+z);foreach(var hit in Physics.RaycastAll(p,Vector3.down,100).OrderByDescending(h=>h.point.y).Take(8))b.AppendLine("HIT "+hit.collider.name+" y="+hit.point.y+" local="+t.InverseTransformPoint(hit.point)+" normal="+hit.normal);}foreach(var r in sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Where(r=>r.gameObject.activeInHierarchy&&Vector3.Distance(r.bounds.ClosestPoint(t.position),t.position)<35).Take(100)){b.AppendLine("NEAR "+r.name+" bounds="+r.bounds+" mesh="+(r.GetComponent<MeshFilter>()?r.GetComponent<MeshFilter>().sharedMesh.name:""));}File.WriteAllText("FinalEnvironmentRoadReview/GunShop-StepProbe.txt",b.ToString());}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/GunShop-StepProbe.txt",e.ToString());}}}
